sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', checks: [], summary: { passed: 0, failed: 0, warnings: 0 } };
  try {
    var plugins = JSON.parse(inputs.plugin_list);

    for (var i = 0; i < plugins.length; i++) {
      var plugin = plugins[i];
      var check = {
        sys_id: plugin.sys_id,
        name: plugin.name,
        target_version: plugin.available_version || plugin.target_version,
        status: 'passed',
        blockers: [],
        warnings: []
      };

      // Check if plugin exists and is accessible
      var gr = new GlideRecordSecure('sys_plugins');
      if (!gr.get(plugin.sys_id)) {
        check.status = 'failed';
        check.blockers.push('Plugin record not found or inaccessible');
        result.summary.failed++;
        result.checks.push(check);
        continue;
      }

      // Check plugin active status
      var isActive = gr.getValue('active');
      if (isActive !== 'active') {
        check.warnings.push('Plugin is currently inactive - will be activated during upgrade');
      }

      // Check for customization conflicts
      var custGr = new GlideRecordSecure('sys_update_xml');
      custGr.addQuery('name', 'STARTSWITH', 'sys_plugins_' + plugin.sys_id);
      custGr.setLimit(5);
      custGr.query();
      if (custGr.getRowCount() > 0) {
        check.warnings.push('Customizations detected that may be affected by upgrade');
        result.summary.warnings++;
      }

      // Validate no active update sets are modifying this plugin
      var usGr = new GlideRecordSecure('sys_update_set');
      usGr.addQuery('state', 'in progress');
      usGr.setLimit(1);
      usGr.query();
      if (usGr.next()) {
        check.warnings.push('Active update set in progress - consider completing before upgrade');
      }

      if (check.blockers.length > 0) {
        check.status = 'failed';
        result.summary.failed++;
      } else {
        result.summary.passed++;
      }

      if (check.warnings.length > 0 && check.status === 'passed') {
        check.status = 'passed_with_warnings';
      }

      result.checks.push(check);
    }
  } catch (e) {
    result.status = 'error';
    result.message = 'Pre-upgrade check failed: ' + e.message;
  }
  return result;
})(inputs);
